import csv, sys, collections as C

d = sys.argv[1]
price = {}
for r in csv.DictReader(open(d + '/product_lines.csv')):
    price[(r['line'], r['model_code'])] = float(r['base_price_eur'])

U = C.defaultdict(int); R = C.defaultdict(float); W = C.defaultdict(set); rows = C.Counter(); miss = 0
for r in csv.DictReader(open(d + '/demand_actuals.csv')):
    p = r['sku'].split('-'); line, mc = p[1], p[2]; m = r['week_start'][:7]
    u = int(r['units_actual']); U[(line, m)] += u; U[('ALL', m)] += u
    W[m].add(r['week_start']); rows[(line, m)] += 1
    pr = price.get((line, mc))
    if pr is None:
        miss += 1; continue
    R[(line, m)] += u * pr; R[('ALL', m)] += u * pr
print('missing price rows', miss)
for m in sorted(W):
    print(m, 'weeks', sorted(W[m]))

N = C.defaultdict(int); Q = C.defaultdict(int); T = C.defaultdict(C.Counter)
for r in csv.DictReader(open(d + '/ncr_records.csv')):
    m = r['ncr_date'][:7]; k = (r['line'], m)
    N[k] += 1; Q[k] += int(r['qty_affected']); T[k][r['ncr_type'] + '/' + r['scrap_or_rework']] += 1
print('NCR months', sorted({k[1] for k in N}))

lines = sorted({k[0] for k in U} | {k[0] for k in N})
print('line month rows units rev ncr qty ncr/1000 qty% units/wk ncr/wk qty/wk')
for l in lines:
    for m in sorted(W):
        u = U[(l, m)]; n = N[(l, m)]; q = Q[(l, m)]; w = len(W[m])
        print(l, m, rows[(l, m)], u, round(R[(l, m)]), n, q,
              round(n / u * 1000, 2) if u else '-', round(q / u * 100, 1) if u else '-',
              round(u / w, 1), round(n / w, 2), round(q / w, 1))
for k in sorted(T):
    if k[0] == 'CRAFT':
        print(k, dict(T[k]))

